    }

import hashlib
import math


def _reject_non_finite(obj):
    if isinstance(obj, float):
        if not math.isfinite(obj):
            raise ValueError("non-finite number")
    elif isinstance(obj, list):
        for item in obj:
            _reject_non_finite(item)
    elif isinstance(obj, dict):
        for value in obj.values():
            _reject_non_finite(value)


def _require_str(value, field):
    if not isinstance(value, str):
        raise ValueError(f"{field} must be a string")
    return value


def _safe_rel_path(value, field):
    _require_str(value, field)
    if value == "" or value != value.strip():
        raise ValueError(f"{field} must be non-empty after strip")
    if value.startswith("/") or "\\" in value or ":" in value:
        raise ValueError(f"{field} is not a safe relative path")
    parts = value.split("/")
    if any(seg in ("", ".", "..") for seg in parts):
        raise ValueError(f"{field} is not a safe relative path")
    return value


def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")
    data = payloads[0]
    if not isinstance(data, dict):
        raise ValueError("input must be an object")
    _reject_non_finite(data)

    files = data.get("files")
    attachments = data.get("attachments")
    recipients = data.get("recipients")
    send_ok = data.get("send_ok")

    if not isinstance(files, list):
        raise ValueError("files must be a list")
    if not isinstance(attachments, list):
        raise ValueError("attachments must be a list")
    if not isinstance(recipients, list):
        raise ValueError("recipients must be a list")
    if not isinstance(send_ok, dict):
        raise ValueError("send_ok must be an object")

    # Build file map: path -> hex
    file_map = {}
    for f in files:
        if not isinstance(f, dict):
            raise ValueError("file entry must be an object")
        path = _safe_rel_path(f.get("path"), "path")
        hexv = f.get("hex")
        if not isinstance(hexv, str):
            raise ValueError("hex must be a string")
        if path in file_map:
            raise ValueError("duplicate file path")
        file_map[path] = hexv

    # Attachments: dedupe, sort, must exist
    att_paths = []
    for a in attachments:
        p = _safe_rel_path(a, "attachment")
        if p not in file_map:
            raise ValueError("attachment not in files")
        att_paths.append(p)
    att_paths = sorted(set(att_paths))

    # Recipients: unique non-empty ids
    recips = []
    for r in recipients:
        if not isinstance(r, str) or r.strip() == "":
            raise ValueError("recipient must be non-empty string")
        if r in recips:
            raise ValueError("duplicate recipient")
        recips.append(r)
    recips = sorted(recips)

    attachments_out = []
    for p in att_paths:
        raw = bytes.fromhex(file_map[p])
        attachments_out.append({"path": p, "sha256": hashlib.sha256(raw).hexdigest()})

    receipts = []
    for r in recips:
        if r not in send_ok:
            raise ValueError("recipient missing from send_ok")
        ok = send_ok[r]
        if not isinstance(ok, bool):
            raise ValueError("send_ok value must be bool")
        receipts.append({"recipient": r, "ok": ok})

    return {"name": contract["name"], "result": {"attachments": attachments_out, "receipts": receipts}}

import math


def _reject_non_finite(obj):
    if isinstance(obj, float):
        if not math.isfinite(obj):
            raise ValueError("non-finite number")
    elif isinstance(obj, list):
        for item in obj:
            _reject_non_finite(item)
    elif isinstance(obj, dict):
        for value in obj.values():
            _reject_non_finite(value)


def _is_safe_relpath(value):
    if not isinstance(value, str):
        return False
    if value == "":
        return False
    if value.startswith("/") or "\\" in value or ":" in value:
        return False
    parts = value.split("/")
    if any(part in ("", ".", "..") for part in parts):
        return False
    return True


def transform(payloads, contract):
    if len(payloads) != len(contract["inputs"]):
        raise ValueError("payload count mismatch")

    payload = payloads[0]
    if isinstance(payload, dict) and set(payload) == {"name", "result"}:
        data = payload["result"]
    else:
        data = payload

    if not isinstance(data, dict):
        raise ValueError("input must be an object")
    _reject_non_finite(data)

    files = data.get("files")
    cleanup_prefix = data.get("cleanup_prefix")

    if not isinstance(files, list):
        raise ValueError("files must be a list")
    if not isinstance(cleanup_prefix, str) or cleanup_prefix == "":
        raise ValueError("cleanup_prefix must be a non-empty string")
    if cleanup_prefix.endswith("/"):
        raise ValueError("cleanup_prefix must not end with slash")
    if not _is_safe_relpath(cleanup_prefix):
        raise ValueError("cleanup_prefix must be a safe relative path")

    prefix_parts = cleanup_prefix.split("/")

    delete = []
    for entry in files:
        if not isinstance(entry, dict):
            raise ValueError("file entry must be an object")
        path = entry.get("path")
        if not isinstance(path, str) or not _is_safe_relpath(path):
            raise ValueError("file path must be a safe relative path")
        parts = path.split("/")
        if len(parts) <= len(prefix_parts):
            continue
        if parts[:len(prefix_parts)] != prefix_parts:
            continue
        if not parts[-1].endswith(".tmp"):
            continue
        delete.append(path)

    delete.sort()

    return {"name": contract["name"], "result": {"delete": delete}}

import math


def _reject_non_finite(obj):
    if isinstance(obj, float):
        if not math.isfinite(obj):
            raise ValueError("non-finite number")
    elif isinstance(obj, list):
        for item in obj:
            _reject_non_finite(item)
    elif isinstance(obj, dict):
        for value in obj.values():
            _reject_non_finite(value)


def _safe_rel_path(value, field):
    if not isinstance(value, str):
        raise ValueError(f"{field} must be a string")
    if value != value.strip() or value == "":
        raise ValueError(f"{field} must be non-empty after strip")
    if value.startswith("/") or "\\" in value or ":" in value:
        raise ValueError(f"{field} is not a safe relative path")
    parts = value.split("/")
    if any(part in ("", ".", "..") for part in parts):
        raise ValueError(f"{field} is not a safe relative path")
    return value


def _unwrap(payload):
    if isinstance(payload, dict) and set(payload) == {"name", "result"}:
        return payload["result"]
    return payload


def transform(payloads, contract):
    if not isinstance(payloads, list):
        raise ValueError("payloads must be a list")
    if not isinstance(contract, dict):
        raise ValueError("contract must be a dict")
    if len(payloads) != len(contract.get("inputs", [])):
        raise ValueError("payload count mismatch")

    snapshot = _unwrap(payloads[0])
    receipts = _unwrap(payloads[1])
    cleanup = _unwrap(payloads[2])

    if not isinstance(snapshot, dict):
        raise ValueError("snapshot must be an object")
    if not isinstance(receipts, dict):
        raise ValueError("receipts must be an object")
    if not isinstance(cleanup, dict):
        raise ValueError("cleanup must be an object")

    _reject_non_finite(snapshot)
    _reject_non_finite(receipts)
    _reject_non_finite(cleanup)

    archive_prefix = _safe_rel_path(snapshot["archive_prefix"], "archive_prefix")

    files = snapshot["files"]
    if not isinstance(files, list):
        raise ValueError("files must be a list")
    file_map = {}
    for f in files:
        if not isinstance(f, dict):
            raise ValueError("file entry must be an object")
        path = _safe_rel_path(f["path"], "path")
        if path in file_map:
            raise ValueError("duplicate file path")
        hexv = f["hex"]
        if not isinstance(hexv, str):
            raise ValueError("hex must be a string")
        file_map[path] = hexv

    attachments = snapshot["attachments"]
    if not isinstance(attachments, list):
        raise ValueError("attachments must be a list")
    seen = set()
    for a in attachments:
        p = _safe_rel_path(a, "attachment")
        if p in seen:
            raise ValueError("duplicate attachment")
        seen.add(p)
        if p not in file_map:
            raise ValueError("attachment not in files")

    # receipts
    rec_list = receipts.get("receipts")
    if not isinstance(rec_list, list):
        raise ValueError("receipts must be a list")
    all_ok = True
    for r in rec_list:
        if not isinstance(r, dict):
            raise ValueError("receipt entry must be an object")
        if r.get("ok") is not True:
            all_ok = False

    # cleanup delete list
    deleted = cleanup.get("delete")
    if not isinstance(deleted, list):
        raise ValueError("cleanup delete must be a list")
    deleted = sorted(deleted)

    moves = []
    blocked = False
    if all_ok and len(rec_list) > 0:
        targets = {}
        for a in attachments:
            to = archive_prefix + "/" + a
            if to in targets:
                raise ValueError("duplicate target")
            targets[to] = a
        # check target existence
        for to in targets:
            if to in file_map:
                raise ValueError("target already exists")
        # cleanup must not overlap move source
        for d in deleted:
            if d in seen:
                raise ValueError("cleanup overlaps move source")
        for a in attachments:
            moves.append({"from": a, "to": archive_prefix + "/" + a})
    else:
        blocked = True

    moves.sort(key=lambda m: m["from"])

    out_files = [{"path": p, "hex": file_map[p]} for p in sorted(file_map)]

    return {
        "name": contract["name"],
        "result": {
            "moves": moves,
            "deleted": deleted,
            "blocked": blocked,
            "files": out_files,
        },
    }
